typedef unsigned char uint8;
typedef unsigned int uint32;

class stringx {
  char *chars;
  void *my_buf;
public:
  stringx();
  stringx &operator=(const stringx &);
};

__asm__(".equ __7stringx, 0x0034D3E0");
__asm__(".equ __as__7stringxRC7stringx, 0x0034E0B8");

class color32 {
public:
  union {
    struct { uint8 b, g, r, a; } c;
    uint32 i;
  };

  color32(uint8 _r, uint8 _g, uint8 _b, uint8 _a = 255) {
    c.b = _b;
    c.g = _g;
    c.r = _r;
    c.a = _a;
  }
};

template<class T>
class vector {
  T *begin;
  T *end;
  T *capacity;
public:
  vector() : begin(0), end(0), capacity(0) {}
};

class anim_texture {
  stringx filename;
  vector<void *> frame_list;
  vector<void *> vc_list;
  unsigned tex_flags;
  unsigned blend_mode;
  float blend_amount;
  color32 diffuse_color;
public:
  anim_texture() : tex_flags(0), diffuse_color(255, 255, 255, 255) {}
};

class material {
public:
  material(const stringx &filename, unsigned additional_mat_flags = 0,
           unsigned additional_tex_flags = 0);
  void set_defaults();
private:
  void build_hash_name();
public:
  stringx material_name;
  stringx texture_filename[4];
  anim_texture diffuse_map[4];
  float u_anim;
  float v_anim;
  float det_u_scale;
  float det_v_scale;
  float det_range;
  float det_alpha_clamp;
  unsigned mat_flags;
};

__asm__(".equ set_defaults__8material, 0x003394C0");
__asm__(".equ build_hash_name__8material, 0x00339538");

material::material(const stringx &filename, unsigned additional_mat_flags,
                   unsigned additional_tex_flags)
{
  set_defaults();
  texture_filename[0] = filename;

#ifndef TARGET_PS2
#error TARGET_PS2 must be defined for the released PS2 constructor
#endif

  build_hash_name();
}
